const classification = $node['AI Classify Urgency & Location']?.json || {};
const languageInfo = $node['AI Language Detect & Translate']?.json || {};
const payload = $node['Extract Request Payload']?.json || {};

const urgency = classification.urgency || 'Medium';
const category = classification.category || 'General';
const location = classification.location || 'Unknown';
const originalLanguage = languageInfo.originalLanguage || payload.originalLanguage || 'en';

const northLocations = ['Noida', 'Delhi', 'Gurgaon', 'Lucknow', 'Patna', 'Uttar Pradesh', 'Bihar', 'Haryana', 'Delhi NCR'];
const southLocations = ['Bangalore', 'Chennai', 'Hyderabad', 'Coimbatore', 'Karnataka', 'Tamil Nadu', 'Telangana', 'Kerala'];
const vernacularLangs = ['hi', 'ta', 'te', 'kn', 'bn', 'mr'];

let matchedRuleId = 'RULE-DEFAULT';
let matchedRuleName = 'General Helpdesk Fallback';
let routedBaseId = process.env.AIRTABLE_BASE_ID || 'appVocalGeneralBase';
let routedTableName = process.env.AIRTABLE_TABLE_NAME || 'Tickets';

if (urgency === 'Critical' || (urgency === 'High' && category === 'Refund')) {
  matchedRuleId = 'RULE-001';
  matchedRuleName = 'Critical & Escalations Routing';
  routedBaseId = process.env.AIRTABLE_CRITICAL_BASE_ID || 'appVocalCriticalBase';
  routedTableName = 'Critical_Escalations';
} else if (northLocations.some(l => location.toLowerCase().includes(l.toLowerCase()))) {
  matchedRuleId = 'RULE-002';
  matchedRuleName = 'North Regional Retail Routing';
  routedBaseId = process.env.AIRTABLE_NORTH_BASE_ID || 'appVocalNorthBase';
  routedTableName = 'North_Retail_Tickets';
} else if (southLocations.some(l => location.toLowerCase().includes(l.toLowerCase()))) {
  matchedRuleId = 'RULE-003';
  matchedRuleName = 'South Regional Retail Routing';
  routedBaseId = process.env.AIRTABLE_SOUTH_BASE_ID || 'appVocalSouthBase';
  routedTableName = 'South_Retail_Tickets';
} else if (category === 'Refund') {
  matchedRuleId = 'RULE-004';
  matchedRuleName = 'Refunds & Payments Topic Routing';
  routedBaseId = process.env.AIRTABLE_FINANCE_BASE_ID || 'appVocalFinanceBase';
  routedTableName = 'Refund_Claims';
} else if (category === 'Delivery') {
  matchedRuleId = 'RULE-005';
  matchedRuleName = 'Delivery & Logistics Topic Routing';
  routedBaseId = process.env.AIRTABLE_LOGISTICS_BASE_ID || 'appVocalLogisticsBase';
  routedTableName = 'Delivery_Issues';
} else if (vernacularLangs.includes(originalLanguage)) {
  matchedRuleId = 'RULE-006';
  matchedRuleName = 'Vernacular Language Queue';
  routedBaseId = process.env.AIRTABLE_VERNACULAR_BASE_ID || 'appVocalVernacularBase';
  routedTableName = 'Vernacular_Queue';
}

return [{
  json: {
    ...payload,
    urgency,
    category,
    location,
    originalLanguage,
    matchedRuleId,
    matchedRuleName,
    routedBaseId,
    routedTableName,
    routedAt: new Date().toISOString()
  }
}];
